export type CrewTemplateVariableKey = (typeof CREW_TEMPLATE_VARIABLE_KEYS)[number]

export interface CrewTemplateVariableDefinition {
  key: CrewTemplateVariableKey
  token: string
  label: string
  description: string
}

export const CREW_TEMPLATE_VARIABLES: readonly CrewTemplateVariableDefinition[] =
  [
    {
      key: "volunteerName",
      token: "{{volunteerName}}",
      label: "Volunteer name",
      description: "The recipient's name",
    },
    {
      key: "eventName",
      token: "{{eventName}}",
      label: "Event name",
      description: "The competition / event name",
    },
    {
      key: "shiftName",
      token: "{{shiftName}}",
      label: "Shift name",
      description: "The assigned shift's name",
    },
    {
      key: "roleName",
      token: "{{roleName}}",
      label: "Role",
      description: "The volunteer's role for the shift",
    },
    {
      key: "shiftDate",
      token: "{{shiftDate}}",
      label: "Shift date",
      description: "The shift's date",
    },
    {
      key: "shiftTime",
      token: "{{shiftTime}}",
      label: "Shift time",
      description: "The shift's start and end time",
    },
    {
      key: "location",
      token: "{{location}}",
      label: "Location",
      description: "The shift's location",
    },
    {
      key: "confirmUrl",
      token: "{{confirmUrl}}",
      label: "Confirm link",
      description: "The volunteer's private confirm/respond link",
    },
    {
      key: "scheduleUrl",
      token: "{{scheduleUrl}}",
      label: "Schedule link",
      description: "The volunteer's schedule link",
    },
  ] as const

/**
 * Which variables are meaningful for each template type. Custom broadcasts have
 * no shift context and no per-assignment confirm link, so they are limited to
 * volunteer/event/schedule variables.
 */
const TEMPLATE_VARIABLE_KEYS_BY_TYPE: Record<
  CrewMessageTemplateType,
  readonly CrewTemplateVariableKey[]
> = {
  [CREW_MESSAGE_TEMPLATE_TYPE.ASSIGNMENT_CONFIRMATION]:
    CREW_TEMPLATE_VARIABLE_KEYS,
  [CREW_MESSAGE_TEMPLATE_TYPE.REMINDER_48_HOUR]: CREW_TEMPLATE_VARIABLE_KEYS,
  [CREW_MESSAGE_TEMPLATE_TYPE.REMINDER_24_HOUR]: CREW_TEMPLATE_VARIABLE_KEYS,
  [CREW_MESSAGE_TEMPLATE_TYPE.CUSTOM_BROADCAST]: [
    "volunteerName",
    "eventName",
    "scheduleUrl",
  ],
}

export function getCrewMessageTemplateVariables(
  type: CrewMessageTemplateType,
): CrewTemplateVariableDefinition[] {
  const allowed = new Set(TEMPLATE_VARIABLE_KEYS_BY_TYPE[type])
  return CREW_TEMPLATE_VARIABLES.filter((variable) => allowed.has(variable.key))
}

